+import { UnigachaInventory } from "./libraries/UnigachaInventory.sol";
+import { UnigachaTypes } from "./types/UnigachaTypes.sol";

 /**
  * @title UnigachaV2
  * @author Velvett
- * @notice Upgraded version of UnigachaV1 with version getter.
- * @dev Minimal upgrade example for testing upgrade safety.
+ * @notice Upgradeable tierless gacha draw contract with timelock-friendly governance controls.
+ * @dev
+ * Governance actions are restricted to the contract owner, which is intended to be an external
+ * TimelockController. Operational permissions are split into draw operators, inventory managers,
+ * and activation managers.
  *
- * @custom:oz-upgrades-from UnigachaV1
+ * @custom:security
+ * This variant does not read `block.*`, but it is still not trustless randomness.
