-contract UnigachaV2 is UnigachaV1 {
-    /**
-     * @notice Returns the contract version.
-     * @return Version string "2.0.0"
-     */
+contract UnigachaV2 is Initializable, OwnableUpgradeable, ReentrancyGuardUpgradeable, UUPSUpgradeable {
+    using UnigachaInventory for UnigachaTypes.Gacha;
+
+    /* ========== ERRORS ========== */
+
+    error GachaNotActive();
+    error GachaAlreadyInitialized();
+    error InvalidArgs();
+    error SoldOut();
+    error NotAuthorized();
+    error LastOneCountExceeded();
+
+    /* ========== STORAGE ========== */
+
+    mapping(uint256 => UnigachaTypes.Gacha) private _gachas;
+    mapping(uint256 => uint256) private _drawCountByGacha;
+    mapping(address => bool) private _admins;
+    mapping(uint256 => bytes32) private _rngStateByGacha;
+    mapping(address => bool) private _inventoryManagers;
+    mapping(address => bool) private _activationManagers;
+
+    /* ========== EVENTS ========== */
+
+    event GachaInitialized(uint256 indexed gachaId, uint256 total);
+    event GachaActivated(uint256 indexed gachaId, bool active);
+    event AdminAdded(address indexed account);
+    event AdminRemoved(address indexed account);
+    event InventoryManagerAdded(address indexed account);
+    event InventoryManagerRemoved(address indexed account);
+    event ActivationManagerAdded(address indexed account);
+    event ActivationManagerRemoved(address indexed account);
+    event GachaUpdated(uint256 indexed gachaId, uint256 total, uint256 remaining, bool active);
+    event Draw(uint256 indexed gachaId, address indexed player, uint256 itemId);
+
+    /* ========== CONSTRUCTOR ========== */
+
+    /// @custom:oz-upgrades-unsafe-allow constructor
+    constructor() {
+        _disableInitializers();
+    }
+
+    /* ========== INITIALIZER ========== */
+
+    function initialize(address initialOwner) public initializer {
+        __Ownable_init(initialOwner);
+        __ReentrancyGuard_init();
+        __UUPSUpgradeable_init();
+    }
+
+    /* ========== UUPS UPGRADE ========== */
+
+    function _authorizeUpgrade(address) internal override onlyOwner { }
+
+    /* ========== MODIFIERS ========== */
+
+    modifier onlyOperator() {
+        _onlyOperator();
+        _;
+    }
+
+    modifier onlyInventoryManager() {
+        _onlyInventoryManager();
+        _;
+    }
+
+    modifier onlyActivationManager() {
+        _onlyActivationManager();
+        _;
+    }
+
+    function _onlyOperator() internal view {
+        if (!_admins[msg.sender]) revert NotAuthorized();
+    }
+
+    function _onlyInventoryManager() internal view {
+        if (msg.sender != owner() && !_inventoryManagers[msg.sender]) revert NotAuthorized();
+    }
+
+    function _onlyActivationManager() internal view {
+        if (msg.sender != owner() && !_activationManagers[msg.sender]) revert NotAuthorized();
+    }
+
+    /* ========== ROLE MANAGEMENT ========== */
+
+    /// @notice Backward-compatible alias for addDrawOperator.
+    function addAdmin(address account) external onlyOwner {
+        if (account == address(0) || _admins[account]) revert InvalidArgs();
+        _admins[account] = true;
+        emit AdminAdded(account);
+    }
+
+    /// @notice Backward-compatible alias for removeDrawOperator.
+    function removeAdmin(address account) external onlyOwner {
+        if (!_admins[account]) revert InvalidArgs();
+        delete _admins[account];
+        emit AdminRemoved(account);
+    }
+
+    /// @notice Backward-compatible alias for isDrawOperator.
+    function isAdmin(address account) external view returns (bool) {
+        return _admins[account];
+    }
+
+    function addDrawOperator(address account) external onlyOwner {
+        if (account == address(0) || _admins[account]) revert InvalidArgs();
+        _admins[account] = true;
+        emit AdminAdded(account);
+    }
+
+    function removeDrawOperator(address account) external onlyOwner {
+        if (!_admins[account]) revert InvalidArgs();
+        delete _admins[account];
+        emit AdminRemoved(account);
+    }
+
+    function isDrawOperator(address account) external view returns (bool) {
+        return _admins[account];
+    }
+
+    function addInventoryManager(address account) external onlyOwner {
+        if (account == address(0) || _inventoryManagers[account]) revert InvalidArgs();
+        _inventoryManagers[account] = true;
+        emit InventoryManagerAdded(account);
+    }
+
+    function removeInventoryManager(address account) external onlyOwner {
+        if (!_inventoryManagers[account]) revert InvalidArgs();
+        delete _inventoryManagers[account];
+        emit InventoryManagerRemoved(account);
+    }
+
+    function isInventoryManager(address account) external view returns (bool) {
+        return _inventoryManagers[account];
+    }
+
+    function addActivationManager(address account) external onlyOwner {
+        if (account == address(0) || _activationManagers[account]) revert InvalidArgs();
+        _activationManagers[account] = true;
+        emit ActivationManagerAdded(account);
+    }
+
+    function removeActivationManager(address account) external onlyOwner {
+        if (!_activationManagers[account]) revert InvalidArgs();
+        delete _activationManagers[account];
+        emit ActivationManagerRemoved(account);
+    }
+
+    function isActivationManager(address account) external view returns (bool) {
+        return _activationManagers[account];
+    }
+
+    /* ========== GACHA MANAGEMENT ========== */
+
+    function initGacha(uint256 gachaId, UnigachaTypes.Item[] calldata items) external onlyInventoryManager {
+        UnigachaTypes.Gacha storage g = _gachas[gachaId];
+        if (g.total != 0) revert GachaAlreadyInitialized();
+        if (items.length == 0) revert InvalidArgs();
+
+        uint256 totalUnits = g.loadItems(items);
+        g.active = false;
+        g.total = totalUnits;
+        g.remaining = totalUnits;
+        _rngStateByGacha[gachaId] = _deriveInitialState(gachaId, items, totalUnits);
+        emit GachaInitialized(gachaId, totalUnits);
+    }
+
+    function setGachaActive(uint256 gachaId, bool active) external onlyActivationManager {
+        UnigachaTypes.Gacha storage g = _gachas[gachaId];
+        if (g.total == 0) revert InvalidArgs();
+        g.active = active;
+        emit GachaActivated(gachaId, active);
+    }
+
+    function updateGacha(uint256 gachaId, UnigachaTypes.Item[] calldata items, bool active)
+        external
+        onlyInventoryManager
+    {
+        UnigachaTypes.Gacha storage g = _gachas[gachaId];
+        if (g.total == 0 || items.length == 0) revert InvalidArgs();
+
+        delete g.items;
+
+        uint256 totalUnits = g.loadItems(items);
+        g.total = totalUnits;
+        g.remaining = totalUnits;
+        g.active = active;
+        _drawCountByGacha[gachaId] = 0;
+        _rngStateByGacha[gachaId] = _deriveInitialState(gachaId, items, totalUnits);
+
+        emit GachaUpdated(gachaId, totalUnits, totalUnits, active);
+    }
+
+    /* ========== USER FUNCTIONS ========== */
+
+    function draw(uint256 gachaId, address player) external onlyOperator nonReentrant returns (uint256 itemId) {
+        UnigachaTypes.Gacha storage g = _gachas[gachaId];
+        if (g.total == 0 || !g.active) revert GachaNotActive();
+        if (g.remaining == 0) revert SoldOut();
+        if (player == address(0)) revert InvalidArgs();
+
+        uint256 salt;
+        unchecked {
+            salt = ++_drawCountByGacha[gachaId];
+        }
+
+        itemId = _pick(gachaId, g, player, salt);
+        emit Draw(gachaId, player, itemId);
+    }
+
+    function drawBatch(uint256 gachaId, address player, uint256 count)
+        external
+        onlyOperator
+        nonReentrant
+        returns (uint256[] memory itemIds)
+    {
+        UnigachaTypes.Gacha storage g = _gachas[gachaId];
+        if (g.total == 0 || !g.active) revert GachaNotActive();
+        if (player == address(0) || count == 0) revert InvalidArgs();
+        if (g.remaining < count) revert SoldOut();
+
+        itemIds = new uint256[](count);
+
+        uint256 baseSeq;
+        unchecked {
+            baseSeq = _drawCountByGacha[gachaId];
+            _drawCountByGacha[gachaId] = baseSeq + count;
+        }
+
+        for (uint256 i; i < count;) {
+            uint256 salt;
+            unchecked {
+                salt = baseSeq + i + 1;
+            }
+            itemIds[i] = _pick(gachaId, g, player, salt);
+            emit Draw(gachaId, player, itemIds[i]);
+            unchecked {
+                ++i;
+            }
+        }
+    }
+
+    /* ========== VIEW FUNCTIONS ========== */
+
+    function getGachaBasic(uint256 gachaId) external view returns (bool active, uint256 remaining, uint256 total) {
+        UnigachaTypes.Gacha storage g = _gachas[gachaId];
+        active = g.active;
+        remaining = g.remaining;
+        total = g.total;
+    }
+
     function version() external pure returns (string memory) {
-        return "2.0.0";
+        return "2.1.0";
+    }
+
+    /* ========== INTERNAL FUNCTIONS ========== */
+
+    function _deriveInitialState(uint256 gachaId, UnigachaTypes.Item[] calldata items, uint256 totalUnits)
+        internal
+        view
+        returns (bytes32 state)
+    {
+        state = keccak256(
+            abi.encodePacked("UNIGACHA_V2_TX_RNG", gachaId, totalUnits, msg.sender, tx.origin, tx.gasprice, msg.data)
+        );
+
+        uint256 itemLen = items.length;
+        for (uint256 i; i < itemLen;) {
+            UnigachaTypes.Item calldata item = items[i];
+            state = keccak256(abi.encodePacked(state, item.id, item.amount, item.isLastOne));
+            unchecked {
+                ++i;
+            }
+        }
+    }
+
+    function _randomIndex(uint256 gachaId, uint256 upper, address player, uint256 salt, uint256 remaining)
+        internal
+        returns (uint256)
+    {
+        bytes memory entropy = abi.encodePacked(
+            _rngStateByGacha[gachaId],
+            gachaId,
+            player,
+            salt,
+            remaining,
+            msg.sender,
+            tx.origin,
+            tx.gasprice,
+            msg.sig,
+            msg.value,
+            msg.data
+        );
+        bytes32 nextState;
+        assembly ("memory-safe") {
+            nextState := keccak256(add(entropy, 0x20), mload(entropy))
+        }
+
+        _rngStateByGacha[gachaId] = nextState;
+        return uint256(nextState) % upper;
+    }
+
+    function _pick(uint256 gachaId, UnigachaTypes.Gacha storage g, address player, uint256 salt)
+        internal
+        returns (uint256 itemId)
+    {
+        uint256 selectionUpper = g.selectionUpper();
+        uint256 r = _randomIndex(gachaId, selectionUpper, player, salt, g.remaining);
+        return g.pickWithRandomIndex(r);
     }
 }

