        assertTrue(implementationAfter != implementationBefore, "implementation should differ from previous impl");
        assertEq(gUpgraded.version(), "2.1.0", "should still expose current V2 version");

        (bool activeAfter, uint256 remainingAfter, uint256 totalAfter) = gUpgraded.getGachaBasic(GACHA_ID);
        assertTrue(activeAfter, "should be active after upgrade");
        assertEq(totalAfter, 10, "total should be preserved");
        assertEq(remainingAfter, 9, "remaining should be preserved");
        assertFalse(gUpgraded.isAdmin(owner), "owner should not become operator after upgrade");
        assertTrue(gUpgraded.isDrawOperator(drawOperator), "draw operator should be preserved after upgrade");
        assertTrue(
