        UnigachaV2 upgraded = UnigachaV2(legacyProxy);
        (bool activeAfter, uint256 remainingAfter, uint256 totalAfter) = upgraded.getGachaBasic(GACHA_ID);

        assertTrue(activeAfter, "gacha should remain active after upgrading from legacy");
        assertEq(totalAfter, 10, "total should be preserved after upgrading from legacy");
        assertEq(remainingAfter, 9, "remaining should be preserved after upgrading from legacy");
        assertFalse(upgraded.isAdmin(owner), "owner should stop being an implicit operator after upgrade");
