 *     --rpc-url $RPC_URL \
 *     --private-key $PRIVATE_KEY \
 *     --broadcast \
 *     --verify
 */
contract DeployUnigachaV1 is Script {
    function run() external {
        // Load owner from environment or use deployer
        address initialOwner = vm.envOr("OWNER", msg.sender);

        console.log("Deploying UnigachaV1 UUPS Proxy...");
        console.log("Initial owner:", initialOwner);

        vm.startBroadcast();

        address proxy =
            Upgrades.deployUUPSProxy("UnigachaV1.sol", abi.encodeCall(UnigachaV1.initialize, (initialOwner)));

        vm.stopBroadcast();

        console.log("UnigachaV1 proxy deployed at:", proxy);
        console.log("Implementation:", Upgrades.getImplementationAddress(proxy));
    }
}

/**
 * @title UpgradeUnigachaV1
 * @notice Upgrades an existing UnigachaV1 proxy to a new implementation.
 * @dev Usage:
 *   PROXY_ADDRESS=0x... forge script script/DeployUnigachaV1.s.sol:UpgradeUnigachaV1 \
 *     --rpc-url $RPC_URL \
 *     --private-key $PRIVATE_KEY \
 *     --broadcast \
 *     --verify
 *
 * Note: The new implementation contract name should be specified in the script.
 * For example, to upgrade to UnigachaV2, change "UnigachaV1.sol" to "UnigachaV2.sol".
 */
contract UpgradeUnigachaV1 is Script {
    function run() external {
        address proxy = vm.envAddress("PROXY_ADDRESS");

        console.log("Upgrading UnigachaV1 proxy:", proxy);
        console.log("Current implementation:", Upgrades.getImplementationAddress(proxy));

        vm.startBroadcast();

        // Upgrade to new implementation
        // Note: Change "UnigachaV1.sol" to the new contract name when upgrading to V2, V3, etc.
        Upgrades.upgradeProxy(proxy, "UnigachaV1.sol", "");

        vm.stopBroadcast();

        console.log("Upgraded to implementation:", Upgrades.getImplementationAddress(proxy));
    }
}

