        legacy.draw(GACHA_ID, user1);

        TimelockController timelock = _deployTimelock();

        vm.prank(owner);
        legacy.transferOwnership(address(timelock));

        address implementationBefore = _implementationOf(proxy);
        address newImpl = address(new UnigachaV2());
        bytes memory payload = abi.encodeWithSignature("upgradeToAndCall(address,bytes)", newImpl, bytes(""));
        bytes32 salt = keccak256("upgrade-v2");

