        assertTrue(upgraded.isDrawOperator(drawOperator), "draw operator should remain configured");
        assertFalse(upgraded.isInventoryManager(drawOperator), "legacy operator should not gain inventory role");
        assertFalse(upgraded.isActivationManager(drawOperator), "legacy operator should not gain activation role");
        assertFalse(upgraded.isAdmin(address(timelock)), "timelock should not become operator implicitly");

        (bool active, uint256 remaining, uint256 total) = upgraded.getGachaBasic(GACHA_ID);
        assertTrue(active, "gacha should remain active");
        assertEq(total, 10, "total should be preserved");
