        uint256 itemId = upgraded.draw(GACHA_ID, user1);
        assertTrue(itemId == 1001 || itemId == 1002 || itemId == 9001, "should draw valid item after upgrade");

        (, uint256 remainingAfter,) = upgraded.getGachaBasic(GACHA_ID);
        assertEq(remainingAfter, 8, "remaining should decrement after operator draw");
