        address proxy =
            address(new ERC1967Proxy(implementation, abi.encodeCall(UnigachaV2.initialize, (address(timelock)))));
        UnigachaV2 g = UnigachaV2(proxy);

        bytes32 roleSalt = keccak256("grant-roles");
        address[] memory targets = new address[](3);
        targets[0] = proxy;
        targets[1] = proxy;
        targets[2] = proxy;

        uint256[] memory values = new uint256[](3);

        bytes[] memory rolePayloads = new bytes[](3);
        rolePayloads[0] = abi.encodeCall(UnigachaV2.addDrawOperator, (drawOperator));
        rolePayloads[1] = abi.encodeCall(UnigachaV2.addInventoryManager, (inventoryManager));
        rolePayloads[2] = abi.encodeCall(UnigachaV2.addActivationManager, (activationManager));

