        assertTrue(g.isDrawOperator(drawOperator), "timelock should add draw operator");
        assertTrue(g.isInventoryManager(inventoryManager), "timelock should add inventory manager");
        assertTrue(g.isActivationManager(activationManager), "timelock should add activation manager");

        UnigachaTypes.Item[] memory items = new UnigachaTypes.Item[](2);
        items[0] = UnigachaTypes.Item({ id: 5001, amount: 2, isLastOne: false });
        items[1] = UnigachaTypes.Item({ id: 5999, amount: 1, isLastOne: true });

        address[] memory managementTargets = new address[](2);
        managementTargets[0] = proxy;
