        );

        vm.prank(executor);
        vm.expectRevert();
        timelock.executeBatch(managementTargets, managementValues, managementPayloads, bytes32(0), batchSalt);

        vm.warp(block.timestamp + MIN_DELAY);

        vm.prank(executor);
        timelock.executeBatch(managementTargets, managementValues, managementPayloads, bytes32(0), batchSalt);

        (bool active, uint256 remaining, uint256 total) = g.getGachaBasic(NEW_GACHA_ID);
        assertTrue(active, "timelock should activate gacha");
        assertEq(total, 3, "timelock should initialize inventory");
        assertEq(remaining, 3, "remaining should equal total after init");

        vm.prank(drawOperator);
        uint256 firstDraw = g.draw(NEW_GACHA_ID, user1);
        assertTrue(firstDraw == 5001, "last-one item should be reserved for the end");

        UnigachaTypes.Item[] memory updatedItems = new UnigachaTypes.Item[](2);
        updatedItems[0] = UnigachaTypes.Item({ id: 7001, amount: 1, isLastOne: false });
        updatedItems[1] = UnigachaTypes.Item({ id: 7999, amount: 1, isLastOne: true });

