        timelock.schedule(proxy, 0, updatePayload, bytes32(0), updateSalt, MIN_DELAY);

        vm.warp(block.timestamp + MIN_DELAY);

        vm.prank(executor);
        timelock.execute(proxy, 0, updatePayload, bytes32(0), updateSalt);

        (, uint256 remainingAfterUpdate, uint256 totalAfterUpdate) = g.getGachaBasic(NEW_GACHA_ID);
        assertEq(totalAfterUpdate, 2, "timelock should replace inventory");
        assertEq(remainingAfterUpdate, 2, "remaining should reset after update");

        bytes32 removeDrawOperatorSalt = keccak256("remove-draw-operator");
        bytes memory removeDrawOperatorPayload = abi.encodeCall(UnigachaV2.removeDrawOperator, (drawOperator));

        vm.prank(proposer);
        timelock.schedule(proxy, 0, removeDrawOperatorPayload, bytes32(0), removeDrawOperatorSalt, MIN_DELAY);

        vm.warp(block.timestamp + MIN_DELAY);

        vm.prank(executor);
        timelock.execute(proxy, 0, removeDrawOperatorPayload, bytes32(0), removeDrawOperatorSalt);

        assertFalse(g.isDrawOperator(drawOperator), "timelock should remove draw operator");

        vm.prank(drawOperator);
        vm.expectRevert(UnigachaV2.NotAuthorized.selector);
        g.draw(NEW_GACHA_ID, user1);
    }

    function testTimelockCanUpdateItsOwnDelay() public {
        TimelockController timelock = _deployTimelock();
        uint256 newDelay = 72 hours;
        bytes32 salt = keccak256("update-delay");
        bytes memory payload = abi.encodeCall(TimelockController.updateDelay, (newDelay));

        vm.prank(proposer);
        timelock.schedule(address(timelock), 0, payload, bytes32(0), salt, MIN_DELAY);

        vm.warp(block.timestamp + MIN_DELAY);

        vm.prank(executor);
        timelock.execute(address(timelock), 0, payload, bytes32(0), salt);

        assertEq(timelock.getMinDelay(), newDelay, "timelock should update its own delay");
    }

    function _deployTimelock() internal returns (TimelockController timelock) {
        address[] memory proposers = new address[](1);
        proposers[0] = proposer;

        address[] memory executors = new address[](1);
        executors[0] = executor;

        timelock = new TimelockController(MIN_DELAY, proposers, executors, owner);
